/* =====================================================================================
   CallInBell - 36_LegalPolicies.sql
   The legal pages: Terms and Conditions (/terms), Privacy Policy (/privacy), Cancellation Policy (/cancellation-policy) and
   Refund Policy (/refund-policy), as MarketingContent rows (PageKey Legal-Terms, Legal-Privacy, Legal-Cancellation, Legal-Refund).

   * Operator details live in PageKey "Legal" (SectionKey "Setting"; Title = the value, Subtitle = its label) and are filled into the
     policy text where it says {LegalName}, {RegisteredAddress}, {SupportEmail}, {SupportPhone}, {GrievanceOfficer},
     {GrievanceEmail}, {GrievancePhone}, {Jurisdiction}, {EffectiveDate}, {Brand}, {Website}. Edit them in the admin console
     (Admin > Legal & policies). This script only inserts missing settings and never overwrites values already set.
   * Policy text: Body uses "\n" between paragraphs; a line starting with "- " is a bullet. Eyebrow holds the section's anchor id.
     Re-running this script updates the policy text to this version.
   * PaymentOrders gains TermsVersion and TermsAcceptedAt: which version of the terms a business accepted before paying, and when.

   Written to match how CallInBell works today (paid plans for businesses through Razorpay, no auto-renewal; customers pay
   businesses directly for services). Have it reviewed by a qualified lawyer before relying on it.
   Idempotent: guarded ALTERs; MERGE on MarketingContent.Code.
   ===================================================================================== */
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET XACT_ABORT ON;
GO

IF COL_LENGTH(N'dbo.PaymentOrders', N'TermsVersion') IS NULL    ALTER TABLE dbo.PaymentOrders ADD TermsVersion nvarchar(40) NULL;
IF COL_LENGTH(N'dbo.PaymentOrders', N'TermsAcceptedAt') IS NULL ALTER TABLE dbo.PaymentOrders ADD TermsAcceptedAt datetimeoffset NULL;
GO

BEGIN TRANSACTION;

/* ---------- Operator details (insert-only: values set in the admin console are kept) ---------- */
MERGE dbo.MarketingContent AS t
USING (VALUES
    (N'LEGAL-SET-Brand',            1,  N'CallInBell',              N'Brand name',                        N'Shown wherever the policies name the platform.'),
    (N'LEGAL-SET-LegalName',        2,  N'Sravana Kumar Penuballi', N'Operator / registered legal name',  N'The person or company that operates CallInBell, exactly as registered.'),
    (N'LEGAL-SET-RegisteredAddress',3,  N'',                        N'Registered office address',         N'Required: the address of the registered office (and branch offices, if any).'),
    (N'LEGAL-SET-Website',          4,  N'www.callinbell.com',      N'Website',                           NULL),
    (N'LEGAL-SET-SupportEmail',     5,  N'',                        N'Customer care email',               N'Required: monitored support email address.'),
    (N'LEGAL-SET-SupportPhone',     6,  N'',                        N'Customer care phone',               N'Recommended: support phone number with calling hours.'),
    (N'LEGAL-SET-GrievanceOfficer', 7,  N'',                        N'Grievance Officer name and designation', N'Required: the person appointed to handle consumer and data complaints.'),
    (N'LEGAL-SET-GrievanceEmail',   8,  N'',                        N'Grievance Officer email',           N'Required.'),
    (N'LEGAL-SET-GrievancePhone',   9,  N'',                        N'Grievance Officer phone',           NULL),
    (N'LEGAL-SET-Jurisdiction',     10, N'',                        N'Courts with jurisdiction (city, state)', N'Where disputes are heard, e.g. the city of the registered office.'),
    (N'LEGAL-SET-EffectiveDate',    11, N'13 October 2026',         N'Effective date (version)',          N'Change this whenever the policies change; businesses accept the version shown here before paying.')
) AS s (Code, SortOrder, Value, Label, Help)
ON t.Code = s.Code
WHEN MATCHED AND (t.PageKey <> N'Legal' OR t.SectionKey <> N'Setting' OR ISNULL(t.Subtitle, N'') <> s.Label OR ISNULL(t.Body, N'') <> ISNULL(s.Help, N'')
                  OR t.SortOrder <> s.SortOrder OR t.IsActive = 0 OR t.IsDeleted = 1)
    THEN UPDATE SET PageKey = N'Legal', SectionKey = N'Setting', Subtitle = s.Label, Body = s.Help, SortOrder = s.SortOrder, IsActive = 1, IsDeleted = 0,
                    ModifiedBy = N'seed', ModifiedOn = SYSDATETIMEOFFSET()
WHEN NOT MATCHED BY TARGET
    THEN INSERT (Code, PageKey, SectionKey, SortOrder, Title, Subtitle, Body, IsActive, CreatedBy, CreatedOn)
         VALUES (s.Code, N'Legal', N'Setting', s.SortOrder, s.Value, s.Label, s.Help, 1, N'seed', SYSDATETIMEOFFSET());

/* ---------- Operator details provided for the Terms and Conditions (13 October 2026): filled only where still empty ---------- */
UPDATE t SET Title = s.Value, ModifiedBy = N'seed', ModifiedOn = SYSDATETIMEOFFSET()
FROM dbo.MarketingContent t
JOIN (VALUES
    (N'LEGAL-SET-LegalName',         N'Sravana Kumar Penuballi'),
    (N'LEGAL-SET-RegisteredAddress', N'PLATIMIUM Pleasant, Flat No. 101, Block A, Bandari Layout, Road No. 8B, Nizampet, Telangana, India - 500090'),
    (N'LEGAL-SET-Website',           N'www.callinbell.com'),
    (N'LEGAL-SET-SupportEmail',      N'pkumar@callinbell.com'),
    (N'LEGAL-SET-SupportPhone',      N'+91 99898 50591'),
    (N'LEGAL-SET-GrievanceOfficer',  N'Sravana Kumar Penuballi'),
    (N'LEGAL-SET-GrievanceEmail',    N'pkumar@callinbell.com'),
    (N'LEGAL-SET-GrievancePhone',    N'+91 99898 50591'),
    (N'LEGAL-SET-Jurisdiction',      N'Hyderabad, Telangana')
) AS s (Code, Value) ON t.Code = s.Code
WHERE ISNULL(t.Title, N'') = N''
   OR (t.Code = N'LEGAL-SET-LegalName' AND t.Title = N'TekOrtus Pvt. Ltd.' AND t.CreatedBy = N'seed' AND t.ModifiedBy IS NULL);

/* ---------- Policy text ---------- */
IF OBJECT_ID('tempdb..#Legal') IS NOT NULL DROP TABLE #Legal;
CREATE TABLE #Legal (
    Code nvarchar(60) PRIMARY KEY, PageKey nvarchar(40), SectionKey nvarchar(40), SortOrder int, Eyebrow nvarchar(80) NULL,
    Title nvarchar(200), Subtitle nvarchar(600) NULL, Body nvarchar(max) NULL);

INSERT INTO #Legal (Code, PageKey, SectionKey, SortOrder, Eyebrow, Title, Subtitle, Body) VALUES
/* ======================= TERMS AND CONDITIONS =======================
   The owner's Terms and Conditions (effective 13 October 2026). Company details are placeholders filled from the legal settings. */
(N'LT-INTRO', N'Legal-Terms', N'Intro', 1, NULL, N'Terms and Conditions',
 N'The terms that govern your use of {Brand}, operated by {LegalName}: accounts, listings, plans and payments, cancellations, refunds, disputes and grievance redressal.', NULL),
(N'LT-01', N'Legal-Terms', N'Section', 1, N'about', N'1. About These Terms', NULL,
 N'{Brand} ("{Brand}", "we", "us" or "our") is an online platform operated by {LegalName} that helps customers discover local businesses, explore services, submit enquiries, request quotations, communicate with service providers and make bookings where those features are available.\nThese Terms and Conditions ("Terms") govern your access to and use of the {Brand} website, applications and related services.\nBy accessing the platform, creating an account, listing a business, purchasing a subscription or completing a transaction, you agree to these Terms and the applicable Privacy Policy, Cancellation Policy and Refund Policy.\nIf you do not agree to these Terms, please discontinue use of the platform.\nWe may update these Terms from time to time. Material changes will be communicated through the website or other appropriate channels where required by law. Changes will not retrospectively remove rights that have already accrued under applicable law.'),
(N'LT-02', N'Legal-Terms', N'Section', 2, N'definitions', N'2. Definitions', NULL,
 N'For these Terms:\n- Customer: A person using {Brand} to discover, contact or book a business.\n- Business or Service Provider: An independent business, professional or service provider listed on {Brand}.\n- Listing: A business profile containing information such as its name, location, contact details, services, photographs and operating hours.\n- Enquiry: A request for information, a callback, a quotation or contact from a Business.\n- Booking: A request or confirmed appointment for a service, depending on the booking status displayed by the platform.\n- Platform Fees: Charges payable to {Brand} for paid listings, subscriptions, advertising or other platform features.\n- Service Charges: Amounts charged by a Business to a Customer for the Business''s products or services.\n- Payment Gateway: A third-party payment service provider, such as Razorpay or PayU, that processes eligible online payments.\n- Plan: A free or paid subscription providing specified business listing or platform features.\n- Refund: A return of all or part of an amount paid, subject to applicable law and the relevant policy.'),
(N'LT-03', N'Legal-Terms', N'Section', 3, N'role', N'3. Role of {Brand}', NULL,
 N'{Brand} provides technology to help Customers discover and connect with local Businesses.\nDepending on the features enabled, the platform may provide:\n- Business discovery and search.\n- Categories, location-based listings and business profiles.\n- Enquiries, callback requests and quotation requests.\n- Booking requests and availability information.\n- Reviews, ratings, offers and promotional listings.\n- Chat, video consultation or communication tools.\n- Paid subscriptions, advertisements and business management features.\nUnless expressly stated otherwise, {Brand} is a platform intermediary connecting Customers with independent Businesses. The Business providing a service is responsible for its own service delivery, pricing, quality, qualifications, licences, warranties, safety and compliance with applicable law.\nA listing, verification indicator, rating or review does not constitute an unconditional guarantee by {Brand} of a Business''s reliability, quality or performance.\n{Brand} will exercise reasonable care in operating its platform but cannot guarantee that every listing, availability status, price or item of third-party information is complete, accurate or current.'),
(N'LT-04', N'Legal-Terms', N'Section', 4, N'accounts', N'4. Eligibility and Accounts', NULL,
 N'1. You must provide accurate and current information when creating or using an account.\n2. You must be legally capable of entering into the relevant agreement. Minors may use the platform only with appropriate parental or lawful guardian involvement and consent, subject to applicable law.\n3. You are responsible for maintaining the confidentiality of your passwords, verification codes and account credentials.\n4. Notify {Brand} promptly if you suspect unauthorised access or misuse of your account.\n5. Business accounts may be used only by the business owner or duly authorised representatives.\n6. {Brand} may request additional information to verify an account, business listing or transaction, subject to applicable law.\n7. We may restrict access where reasonably necessary to protect users, investigate suspected fraud or comply with legal obligations.'),
(N'LT-05', N'Legal-Terms', N'Section', 5, N'customers', N'5. Customer Responsibilities', NULL,
 N'When using {Brand}, you agree to:\n1. Provide truthful information when submitting enquiries, reviews and booking requests.\n2. Confirm service availability, final prices, scope of work, payment arrangements and appointment details directly with the Business where necessary.\n3. Treat Businesses and other users respectfully.\n4. Avoid submitting fraudulent, abusive, misleading or unlawful requests.\n5. Use reviews and ratings to describe genuine experiences.\n6. Avoid sharing sensitive personal or financial information through public reviews or unsecured communication channels.\nA booking request does not necessarily mean that an appointment has been confirmed. The confirmation status displayed by {Brand} or communicated by the Business will determine whether the appointment has been accepted.'),
(N'LT-06', N'Legal-Terms', N'Section', 6, N'businesses', N'6. Business Listing Responsibilities', NULL,
 N'Businesses using {Brand} must:\n1. Provide accurate business names, categories, addresses, contact details, service descriptions, prices and operating hours.\n2. Maintain all licences, registrations, permissions and professional qualifications required for their activities.\n3. Comply with applicable consumer protection, taxation, advertising, privacy and other legal requirements.\n4. Honour accepted bookings or promptly notify Customers of changes or cancellations.\n5. Clearly disclose service charges, additional fees, cancellation conditions and refund arrangements before accepting a Customer''s payment.\n6. Issue invoices or receipts where required by law.\n7. Obtain necessary permissions for photographs, trademarks, logos and other uploaded content.\n8. Avoid fake reviews, misleading claims, impersonation, unlawful services and fraudulent listings.\nBusinesses remain responsible for the services they provide and for resolving service-quality, non-delivery, warranty, pricing and service-payment disputes with their Customers, without prejudice to any rights available under law.\n{Brand} may review, suspend, reject or remove listings that violate these Terms or applicable law.'),
(N'LT-07', N'Legal-Terms', N'Section', 7, N'fees', N'7. Plans, Platform Fees and Taxes', NULL,
 N'{Brand} may offer free and paid business listing plans, subscription features, advertising packages and other services.\n1. The features, duration and prices of each Plan will be displayed on the relevant pricing or checkout page.\n2. Prices will be displayed in Indian Rupees (INR), unless expressly stated otherwise.\n3. Applicable GST and other taxes will be disclosed as required by law.\n4. A paid Plan is activated after the payment has been successfully confirmed and the relevant entitlement has been provisioned.\n5. The Customer or Business should retain the transaction reference, order number and invoice for future enquiries.\n6. A basic listing may remain available under the free plan, subject to the platform''s current features and policies.\n7. {Brand} may revise future Plan prices or features after providing appropriate notice where required. Changes will not alter a prepaid period except as permitted by law and the applicable agreement.\n8. Any promotional offer is subject to its published eligibility criteria, duration and conditions.\nA paid Plan provides access only to the features described at the time of purchase. {Brand} does not guarantee a particular number of leads, bookings, enquiries, customers, search rankings or revenue unless expressly agreed in writing.'),
(N'LT-08', N'Legal-Terms', N'Section', 8, N'payments', N'8. Payment Processing: Razorpay and PayU', NULL,
 N'{Brand} may use third-party payment gateways to process payments for eligible Platform Fees and other authorised transactions.\nRazorpay and PayU are separate payment service providers. A gateway will be available to users only when {Brand} has completed the relevant onboarding, obtained required approvals and enabled the integration for the transaction.\n1. The gateway available at checkout will process the payment according to its applicable terms, security procedures and supported payment methods.\n2. Supported methods may include UPI, debit cards, credit cards, net banking and other methods displayed at checkout.\n3. The payment gateway may collect and process payment information in accordance with its own terms and privacy practices.\n4. {Brand} does not intend to store full card numbers, CVV values, UPI PINs or other payment credentials prohibited from storage by applicable rules.\n5. A payment is considered successful for {Brand}''s purposes only after the payment status is verified through the applicable gateway or authorised payment confirmation mechanism.\n6. A payment receipt or bank debit notification alone may not establish that a Plan has been activated.\n7. Do not repeat a payment while an earlier transaction remains pending. Check the order or billing status first.\n8. Gateway processing fees, taxes and other charges will be handled according to the applicable agreement and disclosed pricing. No separate customer convenience fee will be imposed by {Brand} unless it is lawfully applicable and disclosed before payment.\n9. Banks, card issuers and payment providers may impose their own charges or transaction restrictions.\n{Brand} will not represent itself as a payment gateway or claim to be affiliated with Razorpay or PayU beyond the actual relationship authorised by the relevant provider.'),
(N'LT-09', N'Legal-Terms', N'Section', 9, N'service-payments', N'9. Service Payments and Business Transactions', NULL,
 N'Unless a particular feature expressly states otherwise, {Brand} does not collect Service Charges on behalf of independent Businesses.\nWhere Customers pay Businesses directly:\n- The Business is responsible for collecting the service payment.\n- The Business must provide its applicable payment, cancellation and refund terms before accepting payment.\n- The Business is responsible for service invoices, applicable taxes, warranties and refunds of Service Charges.\n- {Brand} is not responsible for a Business''s failure to deliver a service, except to the extent responsibility is imposed on {Brand} by applicable law or an express agreement.\nIf {Brand} introduces a feature that collects service payments, facilitates marketplace settlements or distributes payments to Businesses, the relevant terms will be disclosed before that feature is used. Additional regulatory requirements or agreements may apply.'),
(N'LT-10', N'Legal-Terms', N'Section', 10, N'plans', N'10. Subscription Duration, Renewal and Plan Changes', NULL,
 N'1. A Plan begins when payment is confirmed and the subscription is activated.\n2. Its duration will be the monthly, annual or other period shown at checkout.\n3. Unless the checkout explicitly states otherwise and the user has provided the required consent, Plans do not automatically renew.\n4. If a Plan is configured for automatic renewal in the future, the renewal frequency, amount, mandate and cancellation process will be disclosed before consent is obtained.\n5. A Business may purchase another Plan when its current Plan expires.\n6. Where a Plan upgrade or downgrade affects an existing subscription, the price, effective date and treatment of any unused period will be disclosed before the change is confirmed.\n7. Unused subscription periods are not automatically transferable or refundable except as provided by the Refund Policy, the purchase terms or applicable law.\n8. A Plan may be suspended where payment is reversed, fraud is reasonably suspected or suspension is required by law, subject to applicable rights and procedures.'),
(N'LT-11', N'Legal-Terms', N'Section', 11, N'cancellation', N'11. Cancellation Policy', NULL,
 N'### 11.1 Cancellation of Business Services\nCustomers should contact the Business directly to cancel or reschedule a service appointment unless {Brand} provides a cancellation feature for that booking.\nThe Business must communicate any applicable cancellation deadline, cancellation fee, refund eligibility and rescheduling conditions before the Customer confirms the service.\nIf a Business cancels an accepted booking, it should promptly notify the Customer and process any refund due under the agreed terms and applicable law.\n### 11.2 Cancellation of {Brand} Plans\nA Business may request cancellation of a paid Plan through the account dashboard or by contacting customer support.\nWhere the Plan does not renew automatically, cancellation prevents future purchases only if the Business does not purchase another Plan. It does not necessarily terminate the already-paid period.\nCancellation does not automatically entitle the user to a refund. Refund eligibility is determined by the Refund Policy, the purchase terms and applicable law.\n### 11.3 Cancellation by {Brand}\n{Brand} may suspend or discontinue a Plan or feature for legitimate operational, security, legal or contractual reasons.\nWhere {Brand} discontinues a prepaid paid feature for reasons not attributable to the user, it will consider an appropriate refund or alternative remedy for the unused portion, subject to the Refund Policy and applicable law.'),
(N'LT-12', N'Legal-Terms', N'Section', 12, N'refunds', N'12. Refund Policy', NULL,
 N'This section should be read together with the separate Refund Policy published on the {Brand} website.\n### 12.1 General Principles\nRefund eligibility depends on the type of payment, the reason for the request, the service delivered and the applicable terms and law.\nA refund will not be denied where a refund or other remedy is required by applicable law.\n### 12.2 Eligible Refund Situations\nSubject to verification and applicable law, refunds may be considered in cases such as:\n- A duplicate payment for the same order.\n- A payment successfully debited but not confirmed or applied to the intended order.\n- A confirmed payment where the purchased Plan or feature was not activated and the issue cannot reasonably be corrected.\n- An incorrect amount charged by {Brand}.\n- A prepaid feature discontinued by {Brand} before the paid period is completed, where a refund or other remedy is due.\n- A booking cancellation where the applicable service terms provide for a refund.\n- Any other circumstance in which a refund is required by law or expressly promised at checkout.\n### 12.3 Non-Eligible Refund Situations\nSubject to applicable law, a refund may not be available merely because:\n- A user changes their mind after using a Plan or feature.\n- A Business has received the advertised benefits of a subscription.\n- A Customer is dissatisfied with a third-party Business''s service where {Brand} did not provide that service and is not responsible for the issue.\n- A user violates these Terms or engages in fraudulent activity.\nThese exclusions do not remove statutory consumer rights or override a specific refund promise made at the time of purchase.\n### 12.4 Refund Requests\nTo request a refund for a payment made to {Brand}, contact:\n- Email: {SupportEmail}\n- Phone: {SupportPhone}\nInclude the order number, transaction reference, payment date, amount, reason for the request and relevant supporting evidence. Do not send your full card number, CVV or UPI PIN.\n{Brand} will review the request and communicate its decision or any additional information required.\n### 12.5 Refund Processing\nApproved refunds will generally be initiated through the original payment method or another method permitted by the payment provider and applicable law.\nThe time taken for the refund to appear in the Customer''s account depends on the payment gateway, bank, card issuer or other financial institution. {Brand} will communicate the available status information and will not guarantee a processing time outside its control.\nAny gateway fees retained or charged to {Brand} will be handled according to the applicable gateway agreement and law. Such fees will not automatically be deducted from a Customer''s refund where doing so would violate applicable law or the disclosed purchase terms.'),
(N'LT-13', N'Legal-Terms', N'Section', 13, N'failed-payments', N'13. Failed, Pending and Duplicate Payments', NULL,
 N'If a payment fails, remains pending or is debited without the corresponding Plan or order being activated:\n1. Check the order status in your {Brand} account, where available.\n2. Avoid making another payment for the same order while the first transaction is unresolved.\n3. Contact {Brand} support with the order number, transaction reference, amount and payment date.\n4. {Brand} will check the transaction status with the relevant payment gateway and take appropriate corrective action.\nWhere a transaction is confirmed as failed and the amount has been debited, the refund or reversal will be handled in accordance with applicable payment-system rules, regulatory requirements and the gateway''s procedures.\nIf a duplicate payment is confirmed, {Brand} will arrange an appropriate refund of the duplicate amount, subject to verification.\nThe applicable refund timeline may depend on the payment method and regulatory requirements. No provision in these Terms reduces any compensation or remedy that may be required by law.'),
(N'LT-14', N'Legal-Terms', N'Section', 14, N'chargebacks', N'14. Chargebacks and Payment Disputes', NULL,
 N'If you believe a payment was unauthorised, incorrect or not properly fulfilled, please contact {Brand} promptly so that the issue can be investigated.\n{Brand} may provide relevant order, invoice, activation, communication and payment records to the applicable gateway, bank or authorised dispute-resolution body when necessary and lawful.\nUsers must not knowingly make false claims or submit fraudulent chargebacks.\nIf a payment is reversed through a bank or gateway dispute, {Brand} will account for that reversal when handling any further refund request to prevent duplicate repayment of the same amount.\n{Brand} may restrict an account where credible evidence of fraud or misuse exists, subject to applicable law and appropriate review.\nNothing in this section prevents a Customer from exercising a legitimate right to dispute a payment through their bank, payment provider or a competent authority.'),
(N'LT-15', N'Legal-Terms', N'Section', 15, N'privacy', N'15. Privacy and Data Protection', NULL,
 N'{Brand} may process personal information to provide services, maintain accounts, communicate with users, respond to enquiries, process authorised payments, prevent fraud and comply with legal obligations.\nInformation may include account details, contact information, business listing data, booking and enquiry records, device or usage information, and transaction references.\nPersonal information may be shared with relevant Businesses, technology providers, payment gateways, hosting providers and lawful authorities when necessary for the stated purposes and permitted by law.\n{Brand} will handle personal information according to its Privacy Policy and applicable Indian data protection requirements.\nUsers should not submit payment credentials, passwords or unnecessary sensitive information in public reviews or enquiries.\nFor details about data collection, use, retention, sharing, security and applicable rights, please consult the Privacy Policy available on the {Brand} website.'),
(N'LT-16', N'Legal-Terms', N'Section', 16, N'content', N'16. Reviews, User Content and Intellectual Property', NULL,
 N'Users retain ownership of content they lawfully submit, subject to the rights granted under these Terms.\nBy submitting business information, photographs, descriptions, reviews or other content, you grant {Brand} a non-exclusive, royalty-free licence to host, reproduce, display and distribute that content as reasonably necessary to operate, promote and improve the platform, subject to applicable law and your privacy rights.\nYou confirm that you have the necessary rights and permissions to submit the content.\nYou must not upload content that infringes another person''s intellectual property rights, violates privacy, misleads users or breaks the law.\nThe {Brand} name, logo, software, design and original platform materials are owned by or licensed to the platform operator. They may not be copied or commercially reused without permission.\nCertain map data, business details or other third-party information may be subject to separate provider terms, attribution requirements and usage restrictions.\n{Brand} may moderate or remove content that violates these Terms or applicable law, following any legally required process.'),
(N'LT-17', N'Legal-Terms', N'Section', 17, N'acceptable-use', N'17. Acceptable Use', NULL,
 N'You must not:\n- Create fake accounts, fraudulent listings or misleading reviews.\n- Impersonate another person or business.\n- Harass, threaten, defraud or unlawfully discriminate against other users.\n- Send unsolicited spam or misuse contact information obtained through the platform.\n- Scrape, copy or systematically collect platform information without authorisation.\n- Introduce malware or attempt to bypass security controls.\n- Interfere with the platform''s operation, availability or integrity.\n- Use {Brand} to promote unlawful services or conduct prohibited by applicable law.\n{Brand} may investigate suspected violations and take proportionate action, including removing content, restricting features, suspending accounts or reporting unlawful activity where appropriate.'),
(N'LT-18', N'Legal-Terms', N'Section', 18, N'third-party', N'18. Third-Party Services and External Links', NULL,
 N'{Brand} may contain links to third-party websites, maps, payment gateways, communication services or other external tools.\nThese services may operate under their own terms, privacy policies and security practices.\n{Brand} does not control every third-party service and is not responsible for its independent content or operations, except where responsibility is imposed by applicable law or an express agreement.\nUsers should review relevant third-party terms before using those services.'),
(N'LT-19', N'Legal-Terms', N'Section', 19, N'suspension', N'19. Suspension and Termination', NULL,
 N'You may stop using {Brand} and request account closure through the available account settings or customer support.\n{Brand} may suspend, restrict or terminate access where reasonably necessary because of:\n- A material breach of these Terms.\n- Suspected fraud or unlawful activity.\n- A security risk or misuse affecting other users.\n- A legal or regulatory requirement.\n- Repeated, substantiated violations of platform policies.\nWhere reasonably practicable and legally permitted, {Brand} will communicate the reason for significant restrictions and provide an appropriate opportunity to respond.\nSuspension or termination does not automatically extinguish accrued payment obligations, valid refund rights or other rights that survive under applicable law.\nIf {Brand} discontinues a prepaid service for reasons not attributable to the user, any refund or alternative remedy will be determined under the Refund Policy and applicable law.'),
(N'LT-20', N'Legal-Terms', N'Section', 20, N'liability', N'20. Disclaimers and Limitation of Liability', NULL,
 N'{Brand} aims to maintain a reliable and useful platform but does not guarantee uninterrupted availability, error-free operation, or the accuracy of every third-party listing or availability indicator.\nInformation supplied by Businesses may change, and Customers should verify important service details directly before relying on them.\nTo the extent permitted by applicable law, {Brand} will not be liable for indirect or consequential losses arising from use of the platform where such exclusion is legally valid.\n{Brand} does not exclude or limit liability that cannot lawfully be excluded or limited, including applicable consumer rights and liability arising from fraud, wilful misconduct or other non-excludable circumstances.\nNothing in these Terms makes an independent Business an employee or agent of {Brand} merely because it is listed on the platform.'),
(N'LT-21', N'Legal-Terms', N'Section', 21, N'indemnity', N'21. Indemnity', NULL,
 N'To the extent permitted by applicable law, a user may be responsible for reasonable losses, claims and expenses directly arising from that user''s unlawful conduct, infringement of third-party rights or material breach of these Terms.\nThis provision does not exclude any statutory protection available to consumers or impose liability beyond what applicable law permits.'),
(N'LT-22', N'Legal-Terms', N'Section', 22, N'grievance', N'22. Grievance Redressal and Customer Support', NULL,
 N'For questions, complaints, payment issues, cancellation requests or refund enquiries, contact:\n### Customer Support\n- Email: {SupportEmail}\n- Phone: {SupportPhone}\n### Grievance Officer\n- Name: {GrievanceOfficer}\n- Email: {GrievanceEmail}\n- Phone: {GrievancePhone}\n- Address: {RegisteredAddress}\nPlease include your name, registered email or mobile number, order or booking reference, and a clear description of the issue. Do not include passwords, full card numbers or UPI PINs.\n{Brand} will acknowledge and address complaints within the timelines applicable to the platform under Indian law. Where the Consumer Protection (E-Commerce) Rules, 2020 apply, the grievance process will be administered in accordance with the applicable requirements, including the prescribed acknowledgement and redressal timelines.\nIf your concern is not resolved, you may approach the National Consumer Helpline at 1915 or through https://consumerhelpline.gov.in/, or approach the appropriate consumer commission or other competent authority.'),
(N'LT-23', N'Legal-Terms', N'Section', 23, N'law', N'23. Governing Law and Disputes', NULL,
 N'These Terms are governed by the laws of India.\nThe parties will endeavour to resolve disputes through good-faith communication and the grievance process.\nSubject to applicable law, statutory consumer remedies and the jurisdiction of competent authorities, courts having appropriate jurisdiction in {Jurisdiction}, may hear disputes arising from these Terms.\nNothing in this clause prevents a consumer from approaching a consumer commission or other authority that has jurisdiction under applicable law.'),
(N'LT-24', N'Legal-Terms', N'Section', 24, N'changes', N'24. Changes to the Platform and These Terms', NULL,
 N'{Brand} may introduce, modify or discontinue features as the platform evolves.\nWe will communicate material changes where required by law or where the change materially affects a paid service or an existing contractual commitment.\nWhere a change requires fresh consent, authorisation or acknowledgement, we will seek it before applying the change.\nThe version applicable to a specific transaction will be interpreted consistently with the terms disclosed at purchase and any mandatory legal requirements.'),
(N'LT-25', N'Legal-Terms', N'Section', 25, N'severability', N'25. Severability', NULL,
 N'If any provision of these Terms is found invalid or unenforceable, the remaining provisions will continue to apply to the extent permitted by law.\nA provision will be interpreted or modified only to the extent necessary to make it lawful and enforceable, without overriding mandatory legal protections.'),
(N'LT-26', N'Legal-Terms', N'Section', 26, N'entire-agreement', N'26. Entire Agreement', NULL,
 N'These Terms, together with the applicable Privacy Policy, Cancellation Policy, Refund Policy and any transaction-specific terms presented before purchase, form the agreement governing your use of {Brand}.\nIf a specific purchase term conflicts with these general Terms, the documents will be interpreted together where possible. Mandatory legal requirements will prevail over any inconsistent contractual provision.'),
(N'LT-27', N'Legal-Terms', N'Section', 27, N'contact', N'27. Contact Us', NULL,
 N'For questions about these Terms or the {Brand} platform:\n### {Brand}\nOperated by {LegalName}\n- Website: {Website}\n- Email: {SupportEmail}\n- Phone: {SupportPhone}\n- Address: {RegisteredAddress}'),

/* ======================= CANCELLATION POLICY ======================= */
(N'LC-INTRO', N'Legal-Cancellation', N'Intro', 1, NULL, N'Cancellation Policy',
 N'How Customers can cancel bookings and requests, how Businesses can cancel bookings and paid Plans, and what happens to payments when something is cancelled.', NULL),
(N'LC-01', N'Legal-Cancellation', N'Section', 1, N'customer-bookings', N'1. Cancelling a booking (Customers)', NULL,
 N'- You can cancel an upcoming booking from My account > Bookings at any time before the appointment starts. The Business is notified straight away.\n- Please cancel as early as possible. Some Businesses set their own notice period or cancellation charge for their services; check the Business''s terms before booking.\n- {Brand} does not collect payment for services, so there is nothing for {Brand} to refund when you cancel a booking. If you paid the Business in advance, ask the Business for a refund under its terms. If you cannot resolve it, contact us and we will help.'),
(N'LC-02', N'Legal-Cancellation', N'Section', 2, N'business-bookings', N'2. Cancelling a booking (Businesses)', NULL,
 N'- A Business can decline or cancel a booking from its dashboard; the Customer is notified.\n- Businesses should cancel only for a genuine reason, as early as possible, and refund any advance the Customer paid directly to them, in line with their published terms and the law.\n- Repeated cancellations or no-shows by a Business may affect its listing.'),
(N'LC-03', N'Legal-Cancellation', N'Section', 3, N'requests', N'3. Enquiries and quotation requests', NULL,
 N'Enquiries, callback requests and quotation requests are free and do not commit you to anything. A quotation becomes binding only when you agree it with the Business.'),
(N'LC-04', N'Legal-Cancellation', N'Section', 4, N'plans', N'4. Cancelling a paid Plan (Businesses)', NULL,
 N'- Paid Plans do not renew automatically, so you never need to cancel to avoid a future charge. When the period you paid for ends, your listing moves to the free basic listing.\n- If you ask us to stop a paid Plan before it ends, it stays active until the end of the period already paid for. Fees for the remaining period are refunded only in the cases listed in the Refund Policy.\n- You can stop a payment before completing it by closing the checkout; nothing is charged.'),
(N'LC-05', N'Legal-Cancellation', N'Section', 5, N'by-us', N'5. Cancellation by {Brand}', NULL,
 N'We may cancel a booking request, suspend a listing or end a Plan if these Terms are broken, if there is a risk to users, or if required by law. If we end a paid Plan for reasons not caused by the Business, we refund the unused part as described in the Refund Policy.'),
(N'LC-06', N'Legal-Cancellation', N'Section', 6, N'help', N'6. Need help?', NULL,
 N'Contact customer care at {SupportEmail} or through the Contact support page, with your booking or order details.'),

/* ======================= REFUND POLICY ======================= */
(N'LR-INTRO', N'Legal-Refund', N'Intro', 1, NULL, N'Refund Policy',
 N'When money paid to {Brand} is refunded, how to ask for a refund, and how long it takes to reach you.', NULL),
(N'LR-01', N'Legal-Refund', N'Section', 1, N'scope', N'1. What this policy covers', NULL,
 N'This policy covers payments made to {Brand}, which today are Platform Fees for paid Plans bought by Businesses.\nPayments for services are made by Customers directly to Businesses. Refunds of those payments are the responsibility of the Business under its own terms and the law. If a Business does not respond to a genuine refund request, contact us and we will help where we can.'),
(N'LR-02', N'Legal-Refund', N'Section', 2, N'failed', N'2. Failed and duplicate payments', NULL,
 N'- Failed payment: if money is debited but the payment is not confirmed and the Plan is not activated, the payment is not captured by {Brand}. The payment gateway returns it automatically to the original payment method, usually within 5 to 7 working days. Your bank may take a few more days to show it.\n- Duplicate payment: if you are charged more than once for the same order, the extra payment is refunded in full to the original payment method.\n- Wrong amount: if you are charged more than the amount shown at checkout, the difference is refunded.\nIf you do not see the money back within 10 working days, contact us with the order number (ORD-...), the date and the amount.'),
(N'LR-03', N'Legal-Refund', N'Section', 3, N'plans', N'3. Refunds for paid Plans', NULL,
 N'Platform Fees for a Plan that has been activated are generally not refundable. We do refund them, in full or for the unused part, in these cases:\n- the Plan was paid for but not activated within 24 hours, and we cannot activate it;\n- paid features of the Plan were unavailable for more than 72 hours in a row because of a fault on our side, and we could not fix it;\n- {Brand} discontinues the Plan or a paid feature during the period you paid for.\nPlans suspended because the Terms were broken are not refunded.'),
(N'LR-04', N'Legal-Refund', N'Section', 4, N'how', N'4. How to request a refund', NULL,
 N'Email {SupportEmail} or use the Contact support page within 30 days of the payment, with your order number (ORD-...), invoice number, the business name and the reason. We acknowledge requests within 48 hours and tell you our decision within 7 working days.'),
(N'LR-05', N'Legal-Refund', N'Section', 5, N'timeline', N'5. How refunds are paid and how long they take', NULL,
 N'- Approved refunds are paid to the original payment method only; we do not refund in cash or to a different account.\n- We start the refund within 7 working days of approving it. After that, banks usually take 5 to 10 working days to credit it. UPI refunds are often faster.\n- The refund includes the GST you paid on the refunded amount, and we issue a credit note where GST law requires one. Payment Gateway Charges are borne by {Brand} and are not deducted from refunds.\n- You will receive the refund reference by email. If the money has not reached you, share the reference with your bank.'),
(N'LR-06', N'Legal-Refund', N'Section', 6, N'chargebacks', N'6. Chargebacks and disputes', NULL,
 N'Please contact us before raising a chargeback; most payment problems are solved faster directly. If a chargeback is raised, we provide the order and payment records to the payment gateway and bank. An amount refunded through a chargeback is not refunded again.'),
(N'LR-07', N'Legal-Refund', N'Section', 7, N'grievance', N'7. Complaints', NULL,
 N'If you are not satisfied with how a refund was handled, write to our Grievance Officer, {GrievanceOfficer}, at {GrievanceEmail}. We acknowledge complaints within 48 hours and aim to resolve them within one month.'),

/* ======================= PRIVACY POLICY ======================= */
(N'LP-INTRO', N'Legal-Privacy', N'Intro', 1, NULL, N'Privacy Policy',
 N'What personal data {Brand} collects, why, who it is shared with, how long it is kept, and how you can access, correct or delete it.', NULL),
(N'LP-01', N'Legal-Privacy', N'Section', 1, N'who', N'1. Who we are', NULL,
 N'{Brand} is operated by {LegalName}, {RegisteredAddress}. We decide how and why your personal data is processed on {Brand}. Questions about privacy can be sent to our Grievance Officer at {GrievanceEmail}.'),
(N'LP-02', N'Legal-Privacy', N'Section', 2, N'data', N'2. Personal data we collect', NULL,
 N'- Account details: name, email address, mobile number, password (stored only as a secure hash), and your city if you choose it.\n- Requests and messages: enquiries, callback and quotation requests, bookings, chats, video call participation, reviews and the details you include in them.\n- Business details (for Business owners): business name, contact details, address, services, photos, videos, and GSTIN if provided.\n- Payment records: plan, amount, order and invoice numbers and payment status. Card, bank and UPI details are handled by the payment gateway; we do not receive full card numbers or PINs.\n- Location: an approximate location from your internet (IP) address. With your permission, your device location, rounded to about 100 metres before it is sent to us, to show businesses in your area. It is used for that search and not stored with your account.\n- Device and usage data: browser type, pages visited, sign-in activity and security logs, and, if you turn on notifications, a push subscription for your browser.'),
(N'LP-03', N'Legal-Privacy', N'Section', 3, N'why', N'3. Why we use it', NULL,
 N'- to create and secure your account and sign you in;\n- to show relevant businesses and search results near you;\n- to send your enquiries, bookings and messages to the Business you chose, and their replies to you;\n- to send notifications you asked for, such as new messages, booking updates and leads;\n- to process Plan payments, issue invoices and handle refunds;\n- to verify listings, moderate reviews, prevent fraud and abuse, and keep the platform secure;\n- to meet legal obligations, such as tax and accounting records and lawful requests from authorities.\nWe process your data on the basis of your consent, to provide the services you request, and where the law permits or requires it. We do not sell your personal data.'),
(N'LP-04', N'Legal-Privacy', N'Section', 4, N'sharing', N'4. Who we share it with', NULL,
 N'- Businesses you contact: your name and the contact details you provide, with your enquiry, booking or message.\n- Service providers who process data for us under contract: hosting and network security, the payment gateway (Razorpay), maps and place search (Google Maps, OpenStreetMap), notification delivery (web push, and SMS or WhatsApp where enabled) and email. Some of them may process data outside India, with safeguards required by law.\n- Authorities, when required by law or to protect the rights and safety of users.'),
(N'LP-05', N'Legal-Privacy', N'Section', 5, N'retention', N'5. How long we keep it', NULL,
 N'We keep personal data while your account is active and as long as needed for the purposes above. When you delete your account, we delete or anonymise your personal data, except records we must keep by law (for example, invoices and payment records for the period required by tax laws) or to resolve disputes.'),
(N'LP-06', N'Legal-Privacy', N'Section', 6, N'rights', N'6. Your rights and choices', NULL,
 N'- Access: ask for a summary of the personal data we hold about you and how it is used.\n- Correction and update: edit most details in your account, or ask us to correct them.\n- Erasure: ask us to delete your account and personal data, subject to records the law requires us to keep.\n- Withdraw consent: for example, turn off notifications or location access in your browser at any time. This does not affect processing already done.\n- Nominate: you may nominate another person to exercise these rights on your behalf in the event of death or incapacity.\n- Grievance: complain to our Grievance Officer; if not satisfied, you may approach the Data Protection Board of India.\nTo exercise these rights, write to {GrievanceEmail} from the email address on your account. We respond within the time required by law.'),
(N'LP-07', N'Legal-Privacy', N'Section', 7, N'storage', N'7. Cookies and local storage', NULL,
 N'We use your browser''s local and session storage to keep you signed in and to remember preferences such as theme and location. We do not use advertising cookies. Third-party services embedded in the platform, such as Google sign-in and the payment checkout, may set their own cookies under their policies.'),
(N'LP-08', N'Legal-Privacy', N'Section', 8, N'security', N'8. Security', NULL,
 N'We use encrypted connections (HTTPS), hashed passwords, token-based sign-in, role-based access, rate limiting and activity logs to protect personal data. No system is completely secure; if a breach affecting your data occurs, we will inform you and the authorities as required by law.'),
(N'LP-09', N'Legal-Privacy', N'Section', 9, N'children', N'9. Children', NULL,
 N'{Brand} is meant for adults. A person under 18 may use it only with the verifiable consent and involvement of a parent or lawful guardian. We do not knowingly track or target advertising at children.'),
(N'LP-10', N'Legal-Privacy', N'Section', 10, N'changes', N'10. Changes and contact', NULL,
 N'We may update this policy; the effective date shows the current version, and we will tell you about significant changes. For privacy questions or requests, contact our Grievance Officer, {GrievanceOfficer}, at {GrievanceEmail} or {GrievancePhone}, or write to {LegalName}, {RegisteredAddress}.');

MERGE dbo.MarketingContent AS t
USING (SELECT Code, PageKey, SectionKey, SortOrder, Eyebrow, Title, Subtitle, REPLACE(Body, N'\n', NCHAR(10)) AS Body FROM #Legal) AS s
ON t.Code = s.Code
WHEN MATCHED AND (t.PageKey <> s.PageKey OR t.Title <> s.Title OR ISNULL(t.Subtitle, N'') <> ISNULL(s.Subtitle, N'') OR ISNULL(t.Body, N'') <> ISNULL(s.Body, N'')
                  OR ISNULL(t.Eyebrow, N'') <> ISNULL(s.Eyebrow, N'') OR t.SectionKey <> s.SectionKey OR t.SortOrder <> s.SortOrder OR t.IsActive = 0 OR t.IsDeleted = 1)
    THEN UPDATE SET PageKey = s.PageKey, SectionKey = s.SectionKey, SortOrder = s.SortOrder, Eyebrow = s.Eyebrow, Title = s.Title, Subtitle = s.Subtitle,
                    Body = s.Body, IsActive = 1, IsDeleted = 0, ModifiedBy = N'seed', ModifiedOn = SYSDATETIMEOFFSET()
WHEN NOT MATCHED BY TARGET
    THEN INSERT (Code, PageKey, SectionKey, SortOrder, Eyebrow, Title, Subtitle, Body, IsActive, CreatedBy, CreatedOn)
         VALUES (s.Code, s.PageKey, s.SectionKey, s.SortOrder, s.Eyebrow, s.Title, s.Subtitle, s.Body, 1, N'seed', SYSDATETIMEOFFSET());


/* Terms sections no longer in this text are switched off. */
UPDATE dbo.MarketingContent SET IsActive = 0, ModifiedBy = N'seed', ModifiedOn = SYSDATETIMEOFFSET()
WHERE PageKey = N'Legal-Terms' AND IsActive = 1 AND Code NOT IN (SELECT Code FROM #Legal WHERE PageKey = N'Legal-Terms');

COMMIT TRANSACTION;
PRINT '36_LegalPolicies.sql completed';
